import {cms} from '@/cms'
import {auth, createBackend, database, github} from 'alinea/backend'
import {createHandler} from 'alinea/next'
import {Pool} from 'pg'

const backend = createBackend(
  auth.basic(
    (username, password) =>
      username === process.env.ALINEA_USERNAME &&
      password === process.env.ALINEA_PASSWORD
  ),
  database({
    driver: 'pg',
    client: new Pool({connectionString: process.env.DATABASE_URL})
  }),
  github({
    authToken: process.env.GITHUB_TOKEN!,
    owner: 'my-org',
    repo: 'my-site',
    branch: 'main',
    rootDir: '',
    contentDir: 'content'
  })
)

const handler = createHandler({cms, backend})

export const GET = handler
export const POST = handler

import {auth} from 'alinea/backend'

auth.basic((username, password) => {
  const user = users[username]
  if (!user || user.password !== password) return false
  return {sub: username, email: username, name: user.name, roles: user.roles}
})

import {auth} from 'alinea/backend'

const issuer = 'https://auth.example.com'

auth.oauth2({
  clientId: process.env.OAUTH_CLIENT_ID!,
  clientSecret: process.env.OAUTH_CLIENT_SECRET,
  authorizationEndpoint: `${issuer}/oauth/authorize`,
  tokenEndpoint: `${issuer}/oauth/token`,
  jwksUri: `${issuer}/.well-known/jwks.json`,
  validateClaims(claims) {
    if (claims.iss !== issuer) throw new Error('Invalid issuer')
    if (claims.aud !== 'alinea') throw new Error('Invalid audience')
  }
})

